    fn append(
        &self,
        session_id: &str,
        source: SessionProjectionSource,
        event: Value,
        fold: impl FnOnce(&mut FoldedState, &Value),
    ) -> Result<ProjectionCursor> {
        let event_json = serde_json::to_string(&event)?;
        let created_ms = now_ms();
        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let tx = db.transaction()?;
        let row = load_row(&tx, &self.epoch, session_id)?.unwrap_or(SessionRow::empty(0)?);
        let seq = row
            .latest
            .checked_add(1)
            .context("session projection cursor exhausted")?;
        let mut state: FoldedState = serde_json::from_str(&row.state_json)?;
        fold(&mut state, &event);
        let state_json = serde_json::to_string(&state)?;
        tx.execute(
            "INSERT INTO session_projection_events(epoch,session_id,seq,source,event_json,encoded_bytes,created_ms) VALUES(?1,?2,?3,?4,?5,?6,?7)",
            params![&*self.epoch, session_id, seq, source_name(source), event_json, event_json.len() as u64, created_ms],
        )?;
        tx.execute(
            "INSERT INTO session_projection_sessions(epoch,session_id,latest_seq,checkpoint_seq,checkpoint_revision,state_json) VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(epoch,session_id) DO UPDATE SET latest_seq=excluded.latest_seq,state_json=excluded.state_json",
            params![&*self.epoch, session_id, seq, row.checkpoint_seq, row.checkpoint_revision, state_json],
        )?;
        tx.commit()?;
        drop(db);
        self.logical_bytes
            .fetch_add(event_json.len() as u64, Ordering::Relaxed);
        let cursor = ProjectionCursor::new(&self.epoch, session_id, seq);
        let _ = self.wakes.send(session_id.to_string());
        // Ordinary appends only trigger pressure compaction; age-based
        // checkpoint compaction runs when a persistence boundary advances.
        if self.logical_bytes.load(Ordering::Relaxed) > self.budget_bytes {
            self.compact(true)?;
        }
        Ok(cursor)
    }

    pub(crate) fn checkpoint(
        &self,
        session_id: &str,
        revision: u64,
        snapshot: Value,
    ) -> Result<Option<ProjectionCursor>> {
        let checkpoint: SessionProjectionCheckpoint =
            serde_json::from_value(snapshot).context("projection checkpoint is not normalized")?;
        anyhow::ensure!(
            matches!(&checkpoint, SessionProjectionCheckpoint::Inline { .. })
                && checkpoint.persistence_revision() == revision,
            "projection checkpoint is not a matching inline snapshot"
        );
        let inline_json = serde_json::to_string(&checkpoint)?;
        let visible = if inline_json.len() <= MAX_CHECKPOINT_BYTES {
            checkpoint
        } else {
            SessionProjectionCheckpoint::Refetch {
                persistence_revision: revision,
            }
        };
        let event_json = serde_json::to_string(&visible)?;
        let created_ms = now_ms();
        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let tx = db.transaction()?;
        let row = load_row(&tx, &self.epoch, session_id)?.unwrap_or(SessionRow::empty(0)?);
        if revision < row.checkpoint_revision {
            anyhow::bail!("session projection checkpoint revision regressed");
        }
        if revision == row.checkpoint_revision && row.checkpoint_json.is_some() {
            return Ok(None);
        }
        let seq = row
            .latest
            .checked_add(1)
            .context("session projection cursor exhausted")?;
        tx.execute(
            "INSERT INTO session_projection_events(epoch,session_id,seq,source,event_json,encoded_bytes,created_ms) VALUES(?1,?2,?3,'checkpoint',?4,?5,?6)",
            params![&*self.epoch, session_id, seq, event_json, event_json.len() as u64, created_ms],
        )?;
        tx.execute(
            "INSERT INTO session_projection_sessions(epoch,session_id,latest_seq,checkpoint_seq,checkpoint_revision,checkpoint_json,state_json) VALUES(?1,?2,?3,?3,?4,?5,?6) ON CONFLICT(epoch,session_id) DO UPDATE SET latest_seq=excluded.latest_seq,checkpoint_seq=excluded.checkpoint_seq,checkpoint_revision=excluded.checkpoint_revision,checkpoint_json=excluded.checkpoint_json",
            params![&*self.epoch, session_id, seq, revision, event_json, row.state_json],
        )?;
        tx.commit()?;
        drop(db);
        self.logical_bytes
            .fetch_add(event_json.len() as u64, Ordering::Relaxed);
        let cursor = ProjectionCursor::new(&self.epoch, session_id, seq);
        let _ = self.wakes.send(session_id.to_string());
        self.compact(false)?;
        Ok(Some(cursor))
    }

    pub(crate) fn snapshot(
        &self,
        session_id: &str,
        file_revision: u64,
        file_snapshot: Value,
    ) -> std::result::Result<SessionProjection, ProjectionReset> {
        if self.is_faulted(session_id) {
            return Err(ProjectionReset::Faulted);
        }

        // Inspect alignment first. A missing/older idle row is repaired only by
        // appending the same visible replacement frame live clients consume —
        // never by silently advancing checkpoint_seq over unrepresented rows.
        let needs_checkpoint = {
            let db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
            match load_row(&db, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)? {
                None => true,
                Some(row) => {
                    let state: FoldedState = serde_json::from_str(&row.state_json)
                        .map_err(|_| ProjectionReset::Faulted)?;
                    if file_revision < row.checkpoint_revision
                        || (file_revision > row.checkpoint_revision && state.active_turn.is_some())
                    {
                        return Err(ProjectionReset::RevisionMismatch);
                    }
                    file_revision > row.checkpoint_revision || row.checkpoint_json.is_none()
                }
            }
        };
        if needs_checkpoint {
            self.checkpoint(session_id, file_revision, file_snapshot)
                .map_err(|_| ProjectionReset::Faulted)?;
        }

        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let tx = db.transaction().map_err(|_| ProjectionReset::Faulted)?;
        let row = load_row(&tx, &self.epoch, session_id)
            .map_err(|_| ProjectionReset::Faulted)?
            .ok_or(ProjectionReset::Faulted)?;
        if row.checkpoint_revision != file_revision {
            return Err(ProjectionReset::RevisionMismatch);
        }
        let state: FoldedState =
            serde_json::from_str(&row.state_json).map_err(|_| ProjectionReset::Faulted)?;
        let checkpoint = row
            .checkpoint_json
            .as_deref()
            .map(serde_json::from_str::<SessionProjectionCheckpoint>)
            .transpose()
            .map_err(|_| ProjectionReset::Faulted)?;
        let pending = query_frames(&tx, &self.epoch, session_id, row.checkpoint_seq, row.latest)
            .map_err(|_| ProjectionReset::Faulted)?;
        tx.commit().map_err(|_| ProjectionReset::Faulted)?;
        drop(db);
        let lease = self.issue_lease(session_id, row.latest);
        Ok(SessionProjection {
            version: 1,
            cursor: ProjectionCursor::new(&self.epoch, session_id, row.latest).to_string(),
            checkpoint_revision: row.checkpoint_revision,
            checkpoint,
            lease_id: lease.0,
            lease_expires_ms: lease.1,
            pending_events: pending,
            state: state.wire(),
        })
    }

    /// Validate and acknowledge only the cursor supplied by a new HTTP request.
    /// Internal SQLite pages must never call this: bytes queued to an SSE channel
    /// are not proof that the client received them.
    pub(crate) fn begin_tail_request(
        &self,
        session_id: &str,
        raw_cursor: &str,
        lease_id: &str,
    ) -> std::result::Result<(), ProjectionReset> {
        let cursor = self.validate_cursor_identity(session_id, raw_cursor)?;
        self.validate_lease(session_id, lease_id, cursor.seq)?;
        self.validate_cursor_position(session_id, cursor.seq)?;
        self.acknowledge_lease(lease_id, cursor.seq)
    }

    pub(crate) fn page_after(
        &self,
        session_id: &str,
        raw_cursor: &str,
        lease_id: &str,
    ) -> std::result::Result<Vec<SessionProjectionFrame>, ProjectionReset> {
        let cursor = self.validate_cursor_identity(session_id, raw_cursor)?;
        self.validate_lease(session_id, lease_id, cursor.seq)?;
        let db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let Some(row) =
            load_row(&db, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)?
        else {
            if cursor.seq == 0 {
                return Ok(Vec::new());
            }
            return Err(ProjectionReset::Future);
        };
        if cursor.seq > row.latest {
            return Err(ProjectionReset::Future);
        }
        let earliest: Option<u64> = db
            .query_row(
                "SELECT MIN(seq) FROM session_projection_events WHERE epoch=?1 AND session_id=?2",
                params![&*self.epoch, session_id],
                |row| row.get(0),
            )
            .optional()
            .map_err(|_| ProjectionReset::Faulted)?
            .flatten();
        if cursor.seq < row.latest
            && earliest.is_none_or(|first| cursor.seq.saturating_add(1) < first)
        {
            return Err(ProjectionReset::Retention);
        }
        let through = cursor.seq.saturating_add(PAGE_LIMIT as u64);
        let frames = query_frames(
            &db,
            &self.epoch,
            session_id,
            cursor.seq,
            through.min(row.latest),
        )
        .map_err(|_| ProjectionReset::Faulted)?;
        drop(db);
        // Fetching or queueing a page is not an acknowledgement. Only renew the
        // expiry; min_seq remains the cursor from begin_tail_request.
        self.renew_lease_expiry(lease_id)?;
        Ok(frames)
    }

    pub(crate) fn fault(&self, session_id: &str, error: &anyhow::Error) {
        self.faults
            .lock()
            .unwrap_or_else(|poison| poison.into_inner())
            .insert(session_id.to_string());
        tracing::error!(session_id, error = %error, "session projection continuity lost");
        let _ = self.wakes.send(session_id.to_string());
    }

    fn is_faulted(&self, session_id: &str) -> bool {
        self.faults
            .lock()
            .unwrap_or_else(|poison| poison.into_inner())
            .contains(session_id)
    }

    fn issue_lease(&self, session_id: &str, min_seq: u64) -> (String, i64) {
        let now = Instant::now();
        let mut leases = self
            .leases
            .lock()
            .unwrap_or_else(|poison| poison.into_inner());
        leases.retain(|_, lease| lease.expires > now);
        if leases.len() >= MAX_LEASES {
            if let Some(oldest) = leases
                .iter()
                .min_by_key(|(_, lease)| lease.expires)
                .map(|(id, _)| id.clone())
            {
                leases.remove(&oldest);
            }
        }
        let id = Uuid::new_v4().to_string();
        let expires_ms = now_ms().saturating_add(self.lease_duration.as_millis() as i64);
        leases.insert(
            id.clone(),
            Lease {
                session_id: session_id.to_string(),
                min_seq,
                expires: now + self.lease_duration,
            },
        );
        (id, expires_ms)
    }

    fn validate_cursor_identity(
        &self,
        session_id: &str,
        raw_cursor: &str,
    ) -> std::result::Result<ProjectionCursor, ProjectionReset> {
        if self.is_faulted(session_id) {
            return Err(ProjectionReset::Faulted);
        }
        let cursor = ProjectionCursor::parse(raw_cursor)?;
        if cursor.epoch.as_str() != self.epoch.as_ref() {
            return Err(ProjectionReset::WrongEpoch);
        }
        if cursor.session_hash != session_hash(session_id) {
            return Err(ProjectionReset::WrongSession);
        }
        Ok(cursor)
    }

    fn validate_cursor_position(
        &self,
        session_id: &str,
        seq: u64,
    ) -> std::result::Result<(), ProjectionReset> {
        let db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let Some(row) =
            load_row(&db, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)?
        else {
            return if seq == 0 {
                Ok(())
            } else {
                Err(ProjectionReset::Future)
            };
        };
        if seq > row.latest {
            return Err(ProjectionReset::Future);
        }
        let earliest: Option<u64> = db
            .query_row(
                "SELECT MIN(seq) FROM session_projection_events WHERE epoch=?1 AND session_id=?2",
                params![&*self.epoch, session_id],
                |row| row.get(0),
            )
            .optional()
            .map_err(|_| ProjectionReset::Faulted)?
            .flatten();
        if seq < row.latest && earliest.is_none_or(|first| seq.saturating_add(1) < first) {
            return Err(ProjectionReset::Retention);
        }
        Ok(())
    }

    fn validate_lease(
        &self,
        session_id: &str,
        lease_id: &str,
        cursor_seq: u64,
    ) -> std::result::Result<(), ProjectionReset> {
        let now = Instant::now();
        let mut leases = self
            .leases
            .lock()
            .unwrap_or_else(|poison| poison.into_inner());
        let Some(lease) = leases.get(lease_id).cloned() else {
            return Err(ProjectionReset::InvalidLease);
        };
        if lease.expires <= now {
            leases.remove(lease_id);
            return Err(ProjectionReset::ExpiredLease);
        }
        if lease.session_id != session_id {
            return Err(ProjectionReset::LeaseSessionMismatch);
        }
        if cursor_seq < lease.min_seq {
            return Err(ProjectionReset::InvalidLease);
        }
        Ok(())
    }

    fn acknowledge_lease(
        &self,
        lease_id: &str,
        acknowledged_seq: u64,
    ) -> std::result::Result<(), ProjectionReset> {
        let now = Instant::now();
        let mut leases = self
            .leases
            .lock()
            .unwrap_or_else(|poison| poison.into_inner());
        let Some(lease) = leases.get_mut(lease_id) else {
            return Err(ProjectionReset::InvalidLease);
        };
        if lease.expires <= now {
            leases.remove(lease_id);
            return Err(ProjectionReset::ExpiredLease);
        }
        if acknowledged_seq < lease.min_seq {
            return Err(ProjectionReset::InvalidLease);
        }
        lease.min_seq = acknowledged_seq;
        lease.expires = now + self.lease_duration;
        Ok(())
    }

    fn renew_lease_expiry(&self, lease_id: &str) -> std::result::Result<(), ProjectionReset> {
        let now = Instant::now();
        let mut leases = self
            .leases
            .lock()
            .unwrap_or_else(|poison| poison.into_inner());
        let Some(lease) = leases.get_mut(lease_id) else {
            return Err(ProjectionReset::InvalidLease);
        };
        if lease.expires <= now {
            leases.remove(lease_id);
            return Err(ProjectionReset::ExpiredLease);
        }
        lease.expires = now + self.lease_duration;
        Ok(())
    }

    fn compact(&self, pressure_only: bool) -> Result<()> {
        let now = Instant::now();
        let protected_by_session = {
            let mut leases = self
                .leases
                .lock()
                .unwrap_or_else(|poison| poison.into_inner());
            leases.retain(|_, lease| lease.expires > now);
            let mut protected: HashMap<String, u64> = HashMap::new();
            for lease in leases.values() {
                protected
                    .entry(lease.session_id.clone())
                    .and_modify(|seq| *seq = (*seq).min(lease.min_seq))
                    .or_insert(lease.min_seq);
            }
            protected
        };
        let cutoff_ms = now_ms().saturating_sub(self.lease_duration.as_millis() as i64);
        let pressure = self.logical_bytes.load(Ordering::Relaxed) > self.budget_bytes;
        if pressure_only && !pressure {
            return Ok(());
        }
        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let rows = {
            let mut stmt = db.prepare(
                "SELECT session_id,checkpoint_seq FROM session_projection_sessions WHERE epoch=?1",
            )?;
            let collected = stmt
                .query_map([&*self.epoch], |row| {
                    Ok((row.get::<_, String>(0)?, row.get::<_, u64>(1)?))
                })?
                .collect::<std::result::Result<Vec<_>, _>>()?;
            collected
        };
        let tx = db.transaction()?;
        for (session_id, checkpoint_seq) in rows {
            let protected = protected_by_session
                .get(&session_id)
                .copied()
                .unwrap_or(checkpoint_seq);
            let through = checkpoint_seq.min(protected);
            if pressure {
                tx.execute(
                    "DELETE FROM session_projection_events WHERE epoch=?1 AND session_id=?2 AND seq<=?3",
                    params![&*self.epoch, session_id, through],
                )?;
            } else {
                tx.execute(
                    "DELETE FROM session_projection_events WHERE epoch=?1 AND session_id=?2 AND seq<=?3 AND created_ms<=?4",
                    params![&*self.epoch, session_id, through, cutoff_ms],
                )?;
            }
        }
        if pressure {
            tx.execute(
                "DELETE FROM session_projection_events WHERE epoch<>?1",
                [&*self.epoch],
            )?;
        }
        tx.commit()?;
        let remaining = db.query_row(
            "SELECT COALESCE(SUM(encoded_bytes),0) FROM session_projection_events",
            [],
            |row| row.get::<_, u64>(0),
        )?;
        self.logical_bytes.store(remaining, Ordering::Relaxed);
        Ok(())
    }
}

fn load_row(
    db: &Connection,
    epoch: &str,
    session_id: &str,
) -> rusqlite::Result<Option<SessionRow>> {
    db.query_row(
        "SELECT latest_seq,checkpoint_seq,checkpoint_revision,checkpoint_json,state_json FROM session_projection_sessions WHERE epoch=?1 AND session_id=?2",
        params![epoch, session_id],
        |row| {
            Ok(SessionRow {
                latest: row.get(0)?,
                checkpoint_seq: row.get(1)?,
                checkpoint_revision: row.get(2)?,
                checkpoint_json: row.get(3)?,
                state_json: row.get(4)?,
            })
        },
    )
    .optional()
}

fn query_frames(
    db: &Connection,
    epoch: &str,
    session_id: &str,
    after: u64,
    through: u64,
) -> Result<Vec<SessionProjectionFrame>> {
    let mut stmt = db.prepare(
        "SELECT seq,source,event_json FROM session_projection_events WHERE epoch=?1 AND session_id=?2 AND seq>?3 AND seq<=?4 ORDER BY seq ASC",
    )?;
    let rows = stmt.query_map(params![epoch, session_id, after, through], |row| {
        Ok((
            row.get::<_, u64>(0)?,

[837 more lines in file. Use offset=851 to continue.]

content.text:
        )
        .map(Some)
    }

    fn append(
        &self,
        session_id: &str,
        source: SessionProjectionSource,
        event: Value,
        fold: impl FnOnce(&mut FoldedState, &Value),
    ) -> Result<ProjectionCursor> {
        let event_json = serde_json::to_string(&event)?;
        let created_ms = now_ms();
        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let tx = db.transaction()?;
        let row = load_row(&tx, &self.epoch, session_id)?.unwrap_or(SessionRow::empty(0)?);
        let seq = row
            .latest
            .checked_add(1)
            .context("session projection cursor exhausted")?;
        let mut state: FoldedState = serde_json::from_str(&row.state_json)?;
        fold(&mut state, &event);
        let state_json = serde_json::to_string(&state)?;
        tx.execute(
            "INSERT INTO session_projection_events(epoch,session_id,seq,source,event_json,encoded_bytes,created_ms) VALUES(?1,?2,?3,?4,?5,?6,?7)",
            params![&*self.epoch, session_id, seq, source_name(source), event_json, event_json.len() as u64, created_ms],
        )?;
        tx.execute(
            "INSERT INTO session_projection_sessions(epoch,session_id,latest_seq,checkpoint_seq,checkpoint_revision,state_json) VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(epoch,session_id) DO UPDATE SET latest_seq=excluded.latest_seq,state_json=excluded.state_json",
            params![&*self.epoch, session_id, seq, row.checkpoint_seq, row.checkpoint_revision, state_json],
        )?;
        tx.commit()?;
        drop(db);
        self.logical_bytes
            .fetch_add(event_json.len() as u64, Ordering::Relaxed);
        let cursor = ProjectionCursor::new(&self.epoch, session_id, seq);
        let _ = self.wakes.send(session_id.to_string());
        // Ordinary appends only trigger pressure compaction; age-based
        // checkpoint compaction runs when a persistence boundary advances.
        if self.logical_bytes.load(Ordering::Relaxed) > self.budget_bytes {
            self.compact(true)?;
        }
        Ok(cursor)
    }

    pub(crate) fn checkpoint(
        &self,
        session_id: &str,
        revision: u64,
        snapshot: Value,
    ) -> Result<Option<ProjectionCursor>> {
        let checkpoint: SessionProjectionCheckpoint =
            serde_json::from_value(snapshot).context("projection checkpoint is not normalized")?;
        anyhow::ensure!(
            matches!(&checkpoint, SessionProjectionCheckpoint::Inline { .. })
                && checkpoint.persistence_revision() == revision,
            "projection checkpoint is not a matching inline snapshot"
        );
        let inline_json = serde_json::to_string(&checkpoint)?;
        let visible = if inline_json.len() <= MAX_CHECKPOINT_BYTES {
            checkpoint
        } else {
            SessionProjectionCheckpoint::Refetch {
                persistence_revision: revision,
            }
        };
        let event_json = serde_json::to_string(&visible)?;
        let created_ms = now_ms();
        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let tx = db.transaction()?;
        let row = load_row(&tx, &self.epoch, session_id)?.unwrap_or(SessionRow::empty(0)?);
        if revision < row.checkpoint_revision {
            anyhow::bail!("session projection checkpoint revision regressed");
        }
        if revision == row.checkpoint_revision && row.checkpoint_json.is_some() {
            return Ok(None);
        }
        let seq = row
            .latest
            .checked_add(1)
            .context("session projection cursor exhausted")?;
        tx.execute(
            "INSERT INTO session_projection_events(epoch,session_id,seq,source,event_json,encoded_bytes,created_ms) VALUES(?1,?2,?3,'checkpoint',?4,?5,?6)",
            params![&*self.epoch, session_id, seq, event_json, event_json.len() as u64, created_ms],
        )?;
        tx.execute(
            "INSERT INTO session_projection_sessions(epoch,session_id,latest_seq,checkpoint_seq,checkpoint_revision,checkpoint_json,state_json) VALUES(?1,?2,?3,?3,?4,?5,?6) ON CONFLICT(epoch,session_id) DO UPDATE SET latest_seq=excluded.latest_seq,checkpoint_seq=excluded.checkpoint_seq,checkpoint_revision=excluded.checkpoint_revision,checkpoint_json=excluded.checkpoint_json",
            params![&*self.epoch, session_id, seq, revision, event_json, row.state_json],
        )?;
        tx.commit()?;
        drop(db);
        self.logical_bytes
            .fetch_add(event_json.len() as u64, Ordering::Relaxed);
        let cursor = ProjectionCursor::new(&self.epoch, session_id, seq);
        let _ = self.wakes.send(session_id.to_string());
        self.compact(false)?;
        Ok(Some(cursor))
    }

    pub(crate) fn snapshot(
        &self,
        session_id: &str,
        file_revision: u64,
        file_snapshot: Value,
    ) -> std::result::Result<SessionProjection, ProjectionReset> {
        if self.is_faulted(session_id) {
            return Err(ProjectionReset::Faulted);
        }

        // Inspect alignment first. A missing/older idle row is repaired only by
        // appending the same visible replacement frame live clients consume —
        // never by silently advancing checkpoint_seq over unrepresented rows.
        let needs_checkpoint = {
            let db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
            match load_row(&db, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)? {
                None => true,
                Some(row) => {
                    let state: FoldedState = serde_json::from_str(&row.state_json)
                        .map_err(|_| ProjectionReset::Faulted)?;
                    if file_revision < row.checkpoint_revision
                        || (file_revision > row.checkpoint_revision && state.active_turn.is_some())
                    {
                        return Err(ProjectionReset::RevisionMismatch);
                    }
                    file_revision > row.checkpoint_revision || row.checkpoint_json.is_none()
                }
            }
        };
        if needs_checkpoint {
            self.checkpoint(session_id, file_revision, file_snapshot)
                .map_err(|_| ProjectionReset::Faulted)?;
        }

        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let tx = db.transaction().map_err(|_| ProjectionReset::Faulted)?;
        let row = load_row(&tx, &self.epoch, session_id)
            .map_err(|_| ProjectionReset::Faulted)?
            .ok_or(ProjectionReset::Faulted)?;
        if row.checkpoint_revision != file_revision {
            return Err(ProjectionReset::RevisionMismatch);
        }
        let state: FoldedState =
            serde_json::from_str(&row.state_json).map_err(|_| ProjectionReset::Faulted)?;
        let checkpoint = row
            .checkpoint_json
            .as_deref()
            .map(serde_json::from_str::<SessionProjectionCheckpoint>)
            .transpose()
            .map_err(|_| ProjectionReset::Faulted)?;
        let pending = query_frames(&tx, &self.epoch, session_id, row.checkpoint_seq, row.latest)
            .map_err(|_| ProjectionReset::Faulted)?;
        tx.commit().map_err(|_| ProjectionReset::Faulted)?;
        drop(db);
        let lease = self.issue_lease(session_id, row.latest);
        Ok(SessionProjection {
            version: 1,
            cursor: ProjectionCursor::new(&self.epoch, session_id, row.latest).to_string(),
            checkpoint_revision: row.checkpoint_revision,
            checkpoint,
            lease_id: lease.0,
            lease_expires_ms: lease.1,
            pending_events: pending,
            state: state.wire(),
        })
    }

    /// Validate and acknowledge only the cursor supplied by a new HTTP request.
    /// Internal SQLite pages must never call this: bytes queued to an SSE channel
    /// are not proof that the client received them.
    pub(crate) fn begin_tail_request(
