    fn issue_lease(&self, session_id: &str, min_seq: u64) -> (String, i64) {
        let now = Instant::now();
        let mut leases = self
            .leases
            .lock()
            .unwrap_or_else(|poison| poison.into_inner());
        leases.retain(|_, lease| lease.expires > now);
        if leases.len() >= MAX_LEASES {
