#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CursorTransition {
    Duplicate,
    Next,
    Reset,
}

fn parse_projection_cursor(raw: &str) -> Option<ProjectionCursor> {
    let mut parts = raw.split(':');
    if parts.next()? != "sp1" {
        return None;
    }
    let epoch = parts.next()?;
    let session_hash = parts.next()?;
    let seq = parts.next()?.parse().ok()?;
    let epoch_bytes = epoch.as_bytes();
    let valid_epoch = epoch_bytes.len() == 36
        && epoch_bytes.iter().enumerate().all(|(index, byte)| {
            if matches!(index, 8 | 13 | 18 | 23) {
                *byte == b'-'
            } else {
                byte.is_ascii_hexdigit()
            }
        });
    if parts.next().is_some()
        || !valid_epoch
        || session_hash.len() != 16
        || !session_hash.bytes().all(|byte| byte.is_ascii_hexdigit())
    {
        return None;
    }
    Some(ProjectionCursor {
        prefix: format!("sp1:{epoch}:{session_hash}"),
        seq,
    })
}

fn projection_cursor_transition(current: &str, incoming: &str) -> CursorTransition {
    let (Some(current), Some(incoming)) = (
        parse_projection_cursor(current),
        parse_projection_cursor(incoming),
    ) else {
        return CursorTransition::Reset;
    };
    if current.prefix != incoming.prefix {
        CursorTransition::Reset
    } else if incoming.seq <= current.seq {
        CursorTransition::Duplicate
    } else if incoming.seq == current.seq.saturating_add(1) {
        CursorTransition::Next
    } else {
        CursorTransition::Reset
    }
}

