                "result" => {
                    let Some(call) = pending.remove(&entry.tool_call_id) else {
                        continue;
                    };
                    if entry.is_error != Some(false) {
                        continue;
                    }
                    let Some(arguments) = call.arguments.as_ref() else {
                        continue;
                    };
                    let Some(id) = arguments.get("id").and_then(Value::as_str) else {
                        continue;
                    };
                    if call.tool_name == "component_render" {
                        components.insert(id.to_string(), arguments.clone());
                    } else {
                        components.remove(id);
                    }
                }
                _ => {}
            }
        }
