fn component_replay_matches(
    tool_context: &[SessionToolContext],
) -> std::collections::HashMap<(String, usize), &SessionToolContext> {
    // Tool call ids should be unique, but malformed persisted history must not
    // let a duplicate select or replay an arbitrary call.
    let mut pending: std::collections::HashMap<&str, &SessionToolContext> =
        std::collections::HashMap::new();
    let mut seen_call_ids = std::collections::HashSet::new();
    let mut blocked_call_ids = std::collections::HashSet::new();
    let mut result_ordinals: std::collections::HashMap<&str, usize> =
        std::collections::HashMap::new();
    let mut matched = std::collections::HashMap::new();

    for entry in tool_context {
        match entry.kind.as_str() {
            "call" => {
                let id = entry.tool_call_id.as_str();
                if !seen_call_ids.insert(id) {
                    // Reuse anywhere in the history is ambiguous. Remove an
                    // earlier match too so no call with this malformed id has a
                    // component effect.
                    blocked_call_ids.insert(id);
                    pending.remove(id);
                    matched.retain(|(matched_id, _), _| matched_id != id);
                    continue;
                }
                if entry.tool_name == "component_render" || entry.tool_name == "component_unmount" {
                    pending.insert(id, entry);
                }
            }
            "result" => {
                let id = entry.tool_call_id.as_str();
                let ordinal = result_ordinals.entry(id).or_default();
                *ordinal += 1;
                if blocked_call_ids.contains(id) {
                    continue;
                }
                if let Some(call) = pending.remove(id) {
                    // The protocol requires explicit success. Missing/failed,
                    // result-before-call, duplicate-call, and repeated-result
                    // records have no component effect.
                    if entry.is_error == Some(false) {
                        matched.insert((id.to_string(), *ordinal), call);
                    }
                }
            }
            _ => {}
        }
    }
    matched
}

fn turns_from_session_transcript(
    entries: Vec<SessionTranscriptEntry>,
    tool_context: &[SessionToolContext],
) -> (Vec<Turn>, Vec<PinnedWidget>) {
    // Derive component effects from the ordered tool-context call/result rail.
    // Transcript result entries provide the point at which each proven effect
    // is inserted into the display-ready turn sequence.
    let component_matches = component_replay_matches(tool_context);
    let mut transcript_result_ordinals: std::collections::HashMap<String, usize> =
        std::collections::HashMap::new();
    let mut turns = Vec::new();
    let mut pinned: Vec<PinnedWidget> = Vec::new();
    for entry in entries {
        if entry.role == "tool" {
            if let Some(call_id) = entry.tool_call_id.as_ref() {
                let ordinal = transcript_result_ordinals
                    .entry(call_id.clone())
                    .or_default();
                *ordinal += 1;
                if entry.is_error == Some(false) {
                    if let Some(component) = component_matches.get(&(call_id.clone(), *ordinal)) {
                        replay_component_call(&mut turns, &mut pinned, component);
                        continue;
                    }
                }
            }
        }

        if entry.text.trim().is_empty() && entry.blocks.is_empty() && entry.tool_name.is_none() {
            continue;
        }
        match entry.role.as_str() {
            "user" => turns.push(Turn::user(entry.text)),
            "assistant" => {
                let mut turn = Turn::assistant(format!("snapshot-{}", turns.len()));
                if entry.is_error.unwrap_or(false) {
                    turn.blocks.push(Block::ToolCall {
                        call_id: format!("snapshot-error-{}", turns.len()),
                        name: "assistant_error".into(),
                        args_preview: String::new(),
                        output: entry.text,
                        status: ToolStatus::Err,
                        expanded: true,
                    });
                } else if entry.blocks.is_empty() {
                    turn.blocks.push(Block::Text(entry.text));
                } else {
                    turn.blocks
                        .extend(entry.blocks.into_iter().map(|block| match block {
                            SessionTranscriptBlock::Text { text } => Block::Text(text),
                            SessionTranscriptBlock::Thinking { thinking } => Block::Thinking {
                                content: thinking,
                                expanded: false,
                            },
                        }));
                }
                turns.push(turn);
            }
            "tool" => {
                let mut turn = Turn::assistant(format!("snapshot-tool-{}", turns.len()));
                let is_error = entry.is_error.unwrap_or(false);
                turn.blocks.push(Block::ToolCall {
                    call_id: format!("snapshot-tool-{}", turns.len()),
                    name: entry.tool_name.unwrap_or_else(|| "tool".into()),
                    args_preview: String::new(),
                    output: entry.text,
                    status: if is_error {
                        ToolStatus::Err
                    } else {
                        ToolStatus::Ok
                    },
                    // Failed tool calls open by default so the error is visible.
                    expanded: is_error,
                });
                turns.push(turn);
            }
            _ => {}
        }
    }
    (turns, pinned)
}

