}

/// One ordered display block inside a normalized transcript entry. `text` on
/// [`SessionTranscriptEntry`] remains the flattened legacy view; exact clients
/// use these blocks so completed thinking keeps its durable visual type.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum SessionTranscriptBlock {
    Text { text: String },
    Thinking { thinking: String },
}

/// One display-ready transcript entry derived from a persisted session message.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SessionTranscriptEntry {
    pub role: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub timestamp_ms: Option<i64>,
    #[serde(default)]
    pub text: String,
    /// Exact ordered text/thinking blocks. Additive: older clients continue to
    /// consume `text`, while projection clients preserve completed thinking.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub blocks: Vec<SessionTranscriptBlock>,
    /// Image blocks attached to this turn, by mime_type only (no base64). Empty
    /// for turns with no images. Lets a replaying client show that an image was
    /// attached even though `text` only carries Text/Thinking content.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub images: Vec<ImageMeta>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tool_call_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tool_name: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub is_error: Option<bool>,
}

/// Tool-call or tool-result context derived from persisted transcript messages.
